const a = [_][4]i32{ .{ 3, -2, 5, 1 }, .{ -4, 7, 0, 6 }, .{ 2, 9, -8, -3 } };
const b = [_][2]i32{ .{ 1, 4 }, .{ -5, 2 }, .{ 6, -1 }, .{ 0, 7 } };
for (a) |row| {
    var product: [2]i32 = @splat(0);
    for (0..2) |j| {
        var value: i32 = 0;
        for (0..4) |k|
            value += row[k] * b[k][j];
        product[j] = value;
    for (product) |value| {
        if (value < 0) {
            try out.print("{d:>5}", .{value});
        } else {
            try out.print("{d:>5}", .{@as(u32, @intCast(value))});
    try out.writeByte('\n');
